//==========================================
// STACK MODULE (HOA 4)
// A stack is LIFO: the last item pushed is the first one popped.
// Two implementations of the same Stack ADT, as in the course:
//   ArrayStack  - items in a dynamic array that doubles when it is full
//   LinkedStack - items in a singly linked list, the top is the head
// Both have the same functions: push, pop, peek, empty, size, clear.
// pop and peek return false (and change nothing) when the stack is empty.
//
// Used in this project by history.h: browser-like Back / Forward (two ArrayStacks)
// and the cart Undo (a LinkedStack), and by graph.h for the iterative depth first search.
//==========================================

//==========================
// ArrayStack<T>
//==========================
template <typename T>
class ArrayStack {
private:
    T* data;            // the array, index 0 is the BOTTOM of the stack
    int capacity;       // how many items fit before the array must grow
    int count;          // how many items are in the stack, the top is data[count - 1]

    // a bigger array, the old items are copied over and the old array is freed
//--- ArrayStack::grow -----------------------------------------------------------------------------
// What    : Doubles the array: copies the items into a bigger array and frees the old one.
// Used by : ArrayStack::push
//--------------------------------------------------------------------------------------------------
    void grow() {
        int newCapacity = capacity * 2;
        T* bigger = new T[newCapacity];
        for (int i = 0; i < count; i++) bigger[i] = data[i];
        delete[] data;
        data = bigger;
        capacity = newCapacity;
    }

public:
//--- ArrayStack::ArrayStack -----------------------------------------------------------------------
// What    : Creates an empty ArrayStack with the given capacity or size (a value that is not
//           positive falls back to 8).
// Used by : doShowcase (screens.h), graphDfsOrder (graph.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    explicit ArrayStack(int startCapacity = 8)
        : data(nullptr), capacity(startCapacity > 0 ? startCapacity : 8), count(0) {
        data = new T[capacity];
    }

//--- ArrayStack::~ArrayStack ----------------------------------------------------------------------
// What    : Frees all memory of the ArrayStack (rule of three).
// Used by : runs by itself when the object goes out of scope or is deleted
//--------------------------------------------------------------------------------------------------
    ~ArrayStack() { delete[] data; }

    // copy constructor: a stack that is a separate copy (rule of three)
//--- ArrayStack::ArrayStack -----------------------------------------------------------------------
// What    : Copy constructor: makes a separate copy of all items (part of the rule of three).
// Used by : tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    ArrayStack(const ArrayStack& other) : data(nullptr), capacity(other.capacity), count(other.count) {
        data = new T[capacity];
        for (int i = 0; i < count; i++) data[i] = other.data[i];
    }

//--- ArrayStack::operator= ------------------------------------------------------------------------
// What    : Copy assignment: replaces the items with a copy of another ArrayStack. The `if (this !=
//           &other)` check makes x = x safe.
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    ArrayStack& operator=(const ArrayStack& other) {
        if (this != &other) {
            T* fresh = new T[other.capacity];
            for (int i = 0; i < other.count; i++) fresh[i] = other.data[i];
            delete[] data;
            data = fresh;
            capacity = other.capacity;
            count = other.count;
        }
        return *this;
    }

//--- ArrayStack::push -----------------------------------------------------------------------------
// What    : Puts an item on top of the stack (the array grows first when it is full).
// Used by : BrowseHistory::goBack (history.h), BrowseHistory::goForward (history.h),
//           BrowseHistory::visit (history.h), doShowcase (screens.h), graphDfsOrder (graph.h),
//           tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    void push(const T& value) {
        if (count == capacity) grow();
        data[count++] = value;
    }

//--- ArrayStack::pop ------------------------------------------------------------------------------
// What    : Removes the top item and gives it back through the parameter.
// Returns : false when the stack is empty
// Used by : BrowseHistory::goBack (history.h), BrowseHistory::goForward (history.h), doShowcase
//           (screens.h), graphDfsOrder (graph.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool pop(T& out) {
        if (count == 0) return false;
        out = data[--count];
        return true;
    }

//--- ArrayStack::peek -----------------------------------------------------------------------------
// What    : Looks at the front or top item without removing it.
// Returns : false when empty
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    bool peek(T& out) const {
        if (count == 0) return false;
        out = data[count - 1];
        return true;
    }

    // the item at a position counted from the BOTTOM (0 = oldest). false when out of range
//--- ArrayStack::at -------------------------------------------------------------------------------
// What    : The item at a position counted from the bottom or the front, without removing it.
// Returns : false when the position is out of range
// Used by : BrowseHistory::backList (history.h)
//--------------------------------------------------------------------------------------------------
    bool at(int indexFromBottom, T& out) const {
        if (indexFromBottom < 0 || indexFromBottom >= count) return false;
        out = data[indexFromBottom];
        return true;
    }

//--- ArrayStack::empty ----------------------------------------------------------------------------
// What    : Tells if there are no items.
// Returns : true when empty
// Used by : BrowseHistory::canGoBack (history.h), BrowseHistory::canGoForward (history.h),
//           doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
    bool empty() const { return count == 0; }
//--- ArrayStack::size -----------------------------------------------------------------------------
// What    : Number of items.
// Returns : the count
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    int size() const { return count; }
//--- ArrayStack::clear ----------------------------------------------------------------------------
// What    : Removes all items.
// Used by : BrowseHistory::visit (history.h)
//--------------------------------------------------------------------------------------------------
    void clear() { count = 0; }
};

//==========================
// LinkedStack<T>
//==========================
template <typename T>
class LinkedStack {
private:
    struct Node {
        T value;
        Node* next;
    };
    Node* head;         // the top of the stack
    int count;

    // make this stack a copy of another one, keeping the same order (top stays the top)
//--- LinkedStack::copyFrom ------------------------------------------------------------------------
// What    : Copies all items of another object, keeping the same order.
// Used by : LinkedStack::LinkedStack, LinkedStack::operator=
//--------------------------------------------------------------------------------------------------
    void copyFrom(const LinkedStack& other) {
        Node* tail = nullptr;
        for (Node* cur = other.head; cur != nullptr; cur = cur->next) {
            Node* node = new Node{cur->value, nullptr};
            if (tail == nullptr) head = node;
            else tail->next = node;
            tail = node;
        }
        count = other.count;
    }

public:
//--- LinkedStack::LinkedStack ---------------------------------------------------------------------
// What    : Creates an empty LinkedStack.
// Used by : tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    LinkedStack() : head(nullptr), count(0) {}

//--- LinkedStack::~LinkedStack --------------------------------------------------------------------
// What    : Frees all memory of the LinkedStack (rule of three).
// Used by : runs by itself when the object goes out of scope or is deleted
//--------------------------------------------------------------------------------------------------
    ~LinkedStack() { clear(); }

//--- LinkedStack::LinkedStack ---------------------------------------------------------------------
// What    : Copy constructor: makes a separate copy of all items (part of the rule of three).
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    LinkedStack(const LinkedStack& other) : head(nullptr), count(0) { copyFrom(other); }

//--- LinkedStack::operator= -----------------------------------------------------------------------
// What    : Copy assignment: replaces the items with a copy of another LinkedStack. The `if (this
//           != &other)` check makes x = x safe.
// Used by : tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    LinkedStack& operator=(const LinkedStack& other) {
        if (this != &other) {
            clear();
            copyFrom(other);
        }
        return *this;
    }

//--- LinkedStack::push ----------------------------------------------------------------------------
// What    : Puts an item on top of the stack (the array grows first when it is full).
// Used by : CartUndo::record (history.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    void push(const T& value) {
        head = new Node{value, head};
        count++;
    }

//--- LinkedStack::pop -----------------------------------------------------------------------------
// What    : Removes the top item and gives it back through the parameter.
// Returns : false when the stack is empty
// Used by : CartUndo::pop (history.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool pop(T& out) {
        if (head == nullptr) return false;
        Node* old = head;
        out = old->value;
        head = old->next;
        delete old;
        count--;
        return true;
    }

//--- LinkedStack::peek ----------------------------------------------------------------------------
// What    : Looks at the front or top item without removing it.
// Returns : false when empty
// Used by : tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool peek(T& out) const {
        if (head == nullptr) return false;
        out = head->value;
        return true;
    }

//--- LinkedStack::empty ---------------------------------------------------------------------------
// What    : Tells if there are no items.
// Returns : true when empty
// Used by : CartUndo::empty (history.h)
//--------------------------------------------------------------------------------------------------
    bool empty() const { return head == nullptr; }
//--- LinkedStack::size ----------------------------------------------------------------------------
// What    : Number of items.
// Returns : the count
// Used by : CartUndo::size (history.h)
//--------------------------------------------------------------------------------------------------
    int size() const { return count; }

//--- LinkedStack::clear ---------------------------------------------------------------------------
// What    : Removes all items.
// Used by : CartUndo::clear (history.h), LinkedStack::operator=, LinkedStack::~LinkedStack
//--------------------------------------------------------------------------------------------------
    void clear() {
        while (head != nullptr) {
            Node* old = head;
            head = head->next;
            delete old;
        }
        count = 0;
    }
};

#endif //STEAM_STACK_H
